<div class="page-heading"><div><p class="eyebrow">Administration</p><h1>Food categories</h1><p>Organize foods into campus-wide or vendor-specific categories.</p></div></div>
<div class="dashboard-grid">
  <section class="panel"><h2 class="panel-title">Categories</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>Scope</th><th>Foods</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($categories as $category): ?><tr><td><strong><?= h($category['name']) ?></strong><div class="muted small"><?= h($category['description'] ?? '') ?></div></td><td><?= $category['vendor_id']?h($category['vendor_name']??'Vendor'):'Campus-wide' ?></td><td><?= (int)$category['food_count'] ?></td><td><?php $status=$category['is_active']?'ACTIVE':'HIDDEN';$badgeLabel=$category['is_active']?'Active':'Inactive';require APP_ROOT . '/views/components/status-badge.php'; ?></td><td><?php if (!$category['vendor_id']): ?><form method="post" action="<?= h(app_url('admin.category.toggle')) ?>" class="inline-form"<?= $category['is_active'] && (int)$category['food_count'] === 0 ? ' data-confirm="Deactivate this category?"' : '' ?>><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$category['id'] ?>"><button class="button button-secondary button-small" type="submit"<?= $category['is_active'] && (int)$category['food_count'] > 0 ? ' disabled title="Reassign foods before deactivating this category."' : '' ?>><?= $category['is_active']?'Deactivate':'Activate' ?></button></form><?php if ($category['is_active'] && (int)$category['food_count'] > 0): ?><span class="field-hint">Reassign foods before deactivating.</span><?php endif; ?><?php else: ?><span class="muted small">Managed by vendor</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
  <section class="panel"><h2 class="panel-title">Add campus category</h2><form method="post" action="<?= h(app_url('admin.category.save')) ?>" class="stack" data-submit-feedback><?= csrf_field() ?><div class="form-field"><label for="name">Category name</label><input id="name" name="name" maxlength="80" value="<?= h(old('name')) ?>"<?= form_field_invalid_attr('name') ?> required><?= field_error_html('name') ?></div><div class="form-field"><label for="description">Description <span class="muted">(optional)</span></label><textarea id="description" name="description" maxlength="240" rows="3"<?= form_field_invalid_attr('description') ?>><?= h(old('description')) ?></textarea><?= field_error_html('description') ?></div><button class="button" type="submit" data-loading-text="Adding…">Add category</button></form></section>
</div>
